SELECT CustomerID, SUM(Revenue) AS TotalSpent
FROM Ecommerce
GROUP BY CustomerID
HAVING TotalSpent > (
    SELECT PERCENTILE_CONT(0.95)
    FROM (
        SELECT SUM(Revenue) AS TotalSpent
        FROM Ecommerce
    ) AS subquery
);

